mapper.update:
UPDATE ds_clickhouse_connection
SET name = #{entity.name}, url = #{entity.url}, username = #{entity.username},
    cluster_name = #{entity.cluster}, password_cipher = #{entity.passwordCipher},
    password_nonce = #{entity.passwordNonce},
    password_key_version = #{entity.passwordKeyVersion},
    password_masked_hint = #{entity.passwordMaskedHint}, enabled = #{entity.enabled},
    revision = revision + 1, updated_at = #{entity.updatedAt}
WHERE id = #{entity.id} AND tenant_id = #{entity.tenantId}
  AND owner_user_id = #{entity.ownerUserId}
  AND revision = #{expectedRevision} AND deleted_at IS NULL

UPDATE ds_clickhouse_connection
SET deleted_at = #{now}
WHERE id = #{id} AND tenant_id = #{tenantId} AND owner_user_id = #{ownerUserId}
  AND revision = #{expectedRevision} AND deleted_at IS NULL
